class ShippingCalculator {
  calculate(type: string, weight: number): number {
    if (type === 'standard') return weight * 1.5;
    if (type === 'express') return weight * 3.0;
    if (type === 'overnight') return weight * 5.0;
    throw new Error('Unknown type');
  }
}

